const $ = (s) => document.querySelector(s);
const app = $('#app');
const DEFAULT_CONNECTION = window.__DEX_CONFIG__ || { url: 'https://bxbpuqzrbvkfrmwohqwd.supabase.co', key: 'sb_publishable_2aAwawQ3-zBwZTu3lE6n6Q__-g2fWsN' };
type Connection = { url: string; key: string };
type AppState = { connection: Connection; session: any; profile: any; role: string; data: Record<string, any>; page: string; busy: boolean; [key: string]: any };
const state: AppState = { connection: {...DEFAULT_CONNECTION}, session: null, profile: null, role: '', data: {}, page: 'overview', busy: false };

const esc = (v) => String(v ?? '—').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = (v) => new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(Number(v || 0));
const date = (v) => v ? new Date(v).toLocaleString('en-KE',{dateStyle:'medium',timeStyle:'short'}) : '—';
const status = (v) => `<span class="badge ${String(v||'').toLowerCase().replaceAll(' ','-')}">${esc(v || 'unknown')}</span>`;
function toast(message, kind='ok') { const node=document.createElement('div'); node.className=`toast ${kind}`; node.textContent=message; document.body.append(node); setTimeout(()=>node.remove(),4200); }
function loading(label='Loading live data…') { return `<div class="empty"><div class="spinner"></div>${label}</div>`; }

async function request(path, options={}) {
  const url = `${state.connection.url.replace(/\/$/,'')}/${path.replace(/^\//,'')}`;
  const headers = { apikey: state.connection.key, Authorization: `Bearer ${state.session.access_token}`, ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers||{}) };
  const response = await fetch(url, {...options, headers});
  if (!response.ok) { const body = await response.text(); throw new Error(body || `Request failed (${response.status})`); }
  const text = await response.text(); return text ? JSON.parse(text) : null;
}
async function authenticate(email, password) {
  const url = `${state.connection.url.replace(/\/$/,'')}/auth/v1/token?grant_type=password`;
  const response = await fetch(url,{method:'POST',headers:{apikey:state.connection.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
  if (!response.ok) throw new Error('Sign-in failed. Check your credentials and backend connection.');
  state.session = await response.json(); await window.dexAdmin.saveSession(state.session); await hydrateIdentity();
}
async function hydrateIdentity() {
  const uid = state.session.user.id;
  const [profiles, roles] = await Promise.all([
    request(`rest/v1/profiles?id=eq.${encodeURIComponent(uid)}&select=*`),
    request(`rest/v1/user_roles?user_id=eq.${encodeURIComponent(uid)}&select=*`)
  ]);
  state.profile = profiles?.[0] || {email:state.session.user.email,name:'Administrator'};
  state.role = roles?.[0]?.role || '';
  if (state.role.toLowerCase() !== 'admin') throw new Error('This account is not an administrator.');
}
async function refreshData() {
  state.busy=true; render();
  const queries = {
    packages: 'rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=250',
    employees: 'api/public/admin/employees',
    notifications: 'rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=100',
    commissions: 'rest/v1/commissions?select=*&order=created_at.desc&limit=150',
    audits: 'rest/v1/audit_logs?select=*&order=timestamp.desc&limit=100',
    broadcasts: 'rest/v1/broadcast_messages?select=*&order=created_at.desc&limit=50'
  };
  const entries = await Promise.all(Object.entries(queries).map(async ([key,path]) => {
    try { const value = await request(path); return [key, key==='employees' ? (value.employees || value || []) : (value || [])]; } catch (e) { console.warn(key,e); return [key,[]]; }
  }));
  state.data=Object.fromEntries(entries); state.busy=false; render();
}
function navItem(id, icon, label) { return `<button class="nav ${state.page===id?'active':''}" data-page="${id}"><span>${icon}</span>${label}</button>`; }
function shell(content) { return `<div class="shell"><aside><div class="brand"><div class="mark">D</div><div><b>DEX</b><small>ADMIN CONSOLE</small></div></div><div class="workspace">OPERATIONS</div>${navItem('overview','◫','Overview')}${navItem('shipments','▣','Shipments')}${navItem('payments','◉','Payments')}${navItem('staff','♚','Staff & access')}${navItem('commissions','◈','Commissions')}<div class="workspace">SYSTEM</div>${navItem('broadcasts','◌','Announcements')}${navItem('audit','◷','Audit trail')}<div class="side-bottom"><div class="admin-dot">${esc((state.profile?.name||'A').slice(0,1))}</div><div><b>${esc(state.profile?.name||'Administrator')}</b><small>System administrator</small></div><button id="signout" title="Sign out">↪</button></div></aside><main><header><div><p class="eyebrow">DEX LOGISTICS / CONTROL CENTER</p><h1>${({overview:'Operations overview',shipments:'Shipment control',payments:'Payment queue',staff:'Staff & access',commissions:'Commission center',broadcasts:'Announcements',audit:'Audit trail'})[state.page]}</h1></div><div class="top-actions"><span class="live"><i></i> LIVE BACKEND</span><button class="secondary" id="refresh">↻ Refresh</button></div></header>${content}</main></div>`; }
function metric(label,value,detail,accent='blue') { return `<article class="metric ${accent}"><span>${label}</span><strong>${value}</strong><small>${detail}</small></article>`; }
function overview() { const p=state.data.packages||[], n=state.data.notifications||[], c=state.data.commissions||[]; const collected=p.filter(x=>['collected','delivered'].includes((x.status||'').toLowerCase())).length, revenue=p.reduce((a,x)=>a+Number(x.amount_due||0),0), pending=n.filter(x=>x.status==='pending').length; const recent=p.slice(0,6); return `<section class="metrics">${metric('Total shipments',p.length,'All time records','blue')}${metric('Collected',collected,`${p.length?Math.round(collected/p.length*100):0}% completion rate`,'green')}${metric('Expected revenue',money(revenue),'From loaded shipments','amber')}${metric('Payment review',pending, pending?'Needs attention':'All caught up','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Shipment flow</h2><p>Current operational distribution</p></div></div><div class="flow">${['received','in transit','arrived','cleared','collected'].map(s=>{const count=p.filter(x=>(x.status||'').toLowerCase()===s).length;return `<div><b>${count}</b><span>${s}</span><i style="width:${p.length?Math.max(8,count/p.length*100):8}%"></i></div>`}).join('')}</div></article><article class="panel attention"><div class="panel-head"><div><h2>Action center</h2><p>Prioritize these items next</p></div></div><button class="action" data-goto="payments"><span>◉</span><div><b>${pending} payment notification${pending===1?'':'s'} awaiting review</b><small>Open payment queue</small></div>›</button><button class="action" data-goto="commissions"><span>◈</span><div><b>${c.filter(x=>x.status==='pending').length} pending commission${c.filter(x=>x.status==='pending').length===1?'':'s'}</b><small>Review employee earnings</small></div>›</button></article></section><section class="panel"><div class="panel-head"><div><h2>Recent shipments</h2><p>Latest records synchronised from the mobile backend</p></div><button class="text-btn" data-goto="shipments">View all →</button></div>${shipmentTable(recent)}</section>`; }
function shipmentTable(rows) { return rows.length?`<div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount due</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.tracking_number)}</b></td><td>${esc(x.consignee_name||x.customers?.name)}</td><td>${esc(x.origin)} <span class="muted">→</span> ${esc(x.destination)}</td><td>${money(x.amount_due)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.tracking_number)}">Manage</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No shipments returned by the backend.</div>`; }
function shipments() { const rows=state.data.packages||[]; return `<section class="toolbar"><div class="search"><span>⌕</span><input id="shipment-search" placeholder="Search tracking number, consignee or phone"></div><button class="primary" id="new-shipment">+ Register shipment</button></section><section class="panel">${shipmentTable(rows)}</section>`; }
function payments() { const rows=state.data.notifications||[]; return `<section class="panel"><div class="panel-head"><div><h2>Payment notifications</h2><p>Mobile payment evidence, STK results and allocations</p></div><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Phone</th><th>Amount</th><th>Evidence</th><th>Received</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.mpesa_receipt||x.notification_number||x.id)}</b></td><td>${esc(x.sender_phone)}</td><td>${money(x.amount)}</td><td>${esc(x.evidence_type)}</td><td>${date(x.uploaded_at||x.timestamp)}</td><td>${status(x.status)}</td></tr>`).join('')}</tbody></table></div></section>`; }
function staff() { const rows=state.data.employees||[]; return `<section class="toolbar"><p class="muted">Manage access through the protected admin endpoint.</p><button class="primary" id="add-staff">+ Add team member</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Code</th><th>Role</th><th>Contact</th><th>Commission</th><th>Access</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.employee_code||x.id)}</td><td>${status(x.role)}</td><td>${esc(x.phone)}</td><td>${x.commission_percentage??0}%</td><td><button class="toggle ${x.is_active?'on':''}" data-employee="${esc(x.id)}" data-active="${x.is_active}"><i></i>${x.is_active?'Active':'Inactive'}</button></td></tr>`).join('')}</tbody></table></div></section>`; }
function commissions() { const rows=state.data.commissions||[]; return `<section class="panel"><div class="panel-head"><div><h2>Employee commissions</h2><p>Approve validated earnings and record payments.</p></div><span class="count">${money(rows.filter(x=>x.status!=='paid').reduce((a,x)=>a+Number(x.amount||0),0))} outstanding</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Employee</th><th>Gross profit</th><th>Rate</th><th>Commission</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.reference||x.order_id)}</b></td><td>${esc(x.employee_id)}</td><td>${money(x.gross_profit)}</td><td>${Number(x.rate||0)}%</td><td>${money(x.amount)}</td><td>${status(x.status)}</td><td>${x.status==='pending'?`<button class="row-btn approve" data-commission="${x.id}">Approve</button>`:x.status==='approved'?`<button class="row-btn paid" data-paid="${x.id}">Mark paid</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`; }
function broadcasts() { const rows=state.data.broadcasts||[]; return `<section class="grid broadcast-grid"><article class="panel compose"><h2>Send announcement</h2><p>Broadcast a concise operational update to the target group.</p><form id="broadcast-form"><label>Audience<select name="target"><option value="all">All staff</option><option value="sales">Sales team</option><option value="operations">Operations</option></select></label><label>Message<textarea name="message" maxlength="500" placeholder="Write an important update…" required></textarea></label><button class="primary" type="submit">Send announcement →</button></form></article><article class="panel"><div class="panel-head"><div><h2>Recent announcements</h2><p>Distributed via the connected backend</p></div></div><div class="timeline">${rows.map(x=>`<div><i></i><b>${esc(x.message)}</b><small>${esc(x.target)} · ${date(x.created_at||x.timestamp)}</small></div>`).join('')||'<div class="empty">No announcements yet.</div>'}</div></article></section>`; }
function audit() { const rows=state.data.audits||[]; return `<section class="toolbar"><p class="muted">Immutable operational record from the backend.</p><button class="secondary" id="export-audit">⇩ Export CSV</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Details</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.timestamp)}</td><td>${status(x.action)}</td><td>${esc(x.actor)}</td><td>${esc(x.details)}</td></tr>`).join('')}</tbody></table></div></section>`; }
function render() { if (!state.session) return renderLogin(); const view=state.busy?loading():({overview,shipments,payments,staff,commissions,broadcasts,audit})[state.page](); app.innerHTML=shell(view); bind(); }
function renderLogin() { const configured=state.connection.url&&state.connection.key; app.innerHTML=`<div class="login"><div class="login-art"><div class="orb"></div><div class="login-brand"><div class="mark">D</div><b>DEX</b><span>LOGISTICS CONTROL</span></div><h1>Move faster.<br><em>See everything.</em></h1><p>A focused operations workspace for the people keeping cargo moving.</p><div class="feature-list"><span>◉ Live backend data</span><span>◈ Role-protected actions</span><span>◷ Secure local session</span></div></div><div class="login-card"><p class="eyebrow">${configured?'ADMINISTRATOR SIGN IN':'CONNECT BACKEND'}</p><h2>${configured?'Welcome back':'One-time connection setup'}</h2><p>${configured?'Use your existing active DEX admin account.':'Use the same Supabase URL and publishable key as the mobile app.'}</p>${configured?`<form id="login-form"><label>Email<input required type="email" name="email" placeholder="admin@company.com"></label><label>Password<input required type="password" name="password" placeholder="••••••••"></label><button class="primary wide">Sign in to console →</button></form><button class="link-btn" id="change-connection">Change backend connection</button>`:`<form id="setup-form"><label>Supabase project URL<input required type="url" name="url" placeholder="https://your-project.supabase.co"></label><label>Publishable / anon key<input required name="key" placeholder="sb_publishable_…"></label><button class="primary wide">Save and continue →</button></form>`}</div></div>`; $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{e.target.querySelector('button').textContent='Signing in…';await authenticate(f.get('email'),f.get('password'));await refreshData()}catch(err){toast(err.message,'error');e.target.querySelector('button').textContent='Sign in to console →'}}); $('#setup-form')?.addEventListener('submit',async e=>{e.preventDefault();state.connection=Object.fromEntries(new FormData(e.target));await window.dexAdmin.saveConnection(state.connection);renderLogin();}); $('#change-connection')?.addEventListener('click',async()=>{state.connection={};await window.dexAdmin.saveConnection({});renderLogin()}); }
function bind() { document.querySelectorAll('[data-page],[data-goto]').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page||b.dataset.goto;render()})); $('#refresh')?.addEventListener('click',refreshData); $('#signout')?.addEventListener('click',async()=>{await window.dexAdmin.clearSession();state.session=null;state.data={};renderLogin()}); $('#shipment-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}); document.querySelectorAll('[data-employee]').forEach(b=>b.addEventListener('click',()=>setEmployee(b.dataset.employee,b.dataset.active!=='true'))); document.querySelectorAll('[data-commission]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.commission,'approve_commission'))); document.querySelectorAll('[data-paid]').forEach(b=>b.addEventListener('click',()=>commission(b.dataset.paid,'mark_commission_paid'))); $('#broadcast-form')?.addEventListener('submit',sendBroadcast); $('#export-audit')?.addEventListener('click',exportAudit); document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>openShipment(b.dataset.track))); $('#add-staff')?.addEventListener('click',addStaff); $('#new-shipment')?.addEventListener('click',()=>toast('Shipment registration remains available in the mobile receiving workflow.','error')); }
async function setEmployee(id,is_active) { try { await request('api/public/admin/employees',{method:'PATCH',body:JSON.stringify({employee_id:id,is_active})});toast(`Account ${is_active?'activated':'deactivated'}.`);await refreshData();}catch(e){toast(`Access update failed: ${e.message}`,'error')} }
async function commission(id,rpc) { try { await request(`rest/v1/rpc/${rpc}`,{method:'POST',body:JSON.stringify({commission_id:id})});toast(rpc==='approve_commission'?'Commission approved.':'Commission marked paid.');await refreshData()}catch(e){toast(`Action failed: ${e.message}`,'error')} }
async function sendBroadcast(e) { e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try { await request('rest/v1/broadcast_messages',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({...f,sender:state.profile.name})});toast('Announcement sent.');e.target.reset();await refreshData()}catch(err){toast(`Could not send: ${err.message}`,'error')} }
function exportAudit(){const rows=state.data.audits||[];const csv=['Time,Action,Actor,Details',...rows.map(x=>[x.timestamp,x.action,x.actor,x.details].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`dex-audit-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}
function openShipment(track){const p=(state.data.packages||[]).find(x=>x.tracking_number===track);if(p)toast(`${track}: ${p.status} · ${money(p.amount_due)}`);}
function addStaff(){toast('Use the mobile admin workflow to create staff accounts; this keeps account provisioning behind the existing protected endpoint.','error');}
function renderLogin() {
  app.innerHTML = `<div class="login"><div class="login-art"><div class="orb"></div><div class="login-brand"><img style="width:240px;border-radius:12px" src="assets/dex-logo.png" alt="DEX Logistics"></div><h1>Move faster.<br><em>See everything.</em></h1><p>A focused operations workspace for the people keeping DEX Logistics cargo moving.</p><div class="feature-list"><span>◉ Live backend data</span><span>◈ Role-protected actions</span><span>◷ Secure local session</span></div></div><div class="login-card"><img style="width:96px;border-radius:10px;margin-bottom:18px" src="assets/dex-logo.png" alt="DEX Logistics"><p class="eyebrow">DEX LOGISTICS · ADMINISTRATOR SIGN IN</p><h2>Welcome back</h2><p>Sign in with your active DEX administrator account.</p><form id="login-form"><label>Email<input required type="email" name="email" placeholder="admin@dexcargo.com"></label><label>Password<input required type="password" name="password" placeholder="••••••••"></label><button class="primary wide">Sign in to console →</button></form></div></div>`;
  $('#login-form').addEventListener('submit', async e => { e.preventDefault(); const f = new FormData(e.target); try { await authenticate(f.get('email'), f.get('password')); await refreshData(); } catch (err) { toast(err.message, 'error'); } });
}
async function request(path, options = {}, retried = false) {
  const url = `${state.connection.url.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;
  const headers = { apikey: state.connection.key, Authorization: `Bearer ${state.session.access_token}`, ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) };
  const response = await fetch(url, {...options, headers});
  if (response.status === 401 && !retried && state.session.refresh_token) {
    const refresh = await fetch(`${state.connection.url}/auth/v1/token?grant_type=refresh_token`, {method:'POST', headers:{apikey:state.connection.key,'Content-Type':'application/json'}, body:JSON.stringify({refresh_token:state.session.refresh_token})});
    if (refresh.ok) { state.session = await refresh.json(); await window.dexAdmin.saveSession(state.session); return request(path, options, true); }
  }
  if (!response.ok) { const body = await response.text(); throw new Error(body || `Request failed (${response.status})`); }
  const text = await response.text(); return text ? JSON.parse(text) : null;
}
async function refreshData() {
  state.busy = true; render();
  const sources = { packages:'rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=250', notifications:'rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=100', commissions:'rest/v1/commissions?select=*&order=created_at.desc&limit=150', audits:'rest/v1/audit_logs?select=*&order=timestamp.desc&limit=100', broadcasts:'rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50', employees:'api/public/admin/employees' };
  const results = await Promise.all(Object.entries(sources).map(async ([name,path]) => { try { const value = await request(path); return [name, name === 'employees' ? (value.employees || value || []) : (value || [])]; } catch (error) { console.error(name,error); return [name,[]]; } }));
  state.data = Object.fromEntries(results); state.busy = false; render();
}
function shipmentTable(rows) { return rows.length ? `<div class="table-wrap"><table><thead><tr><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount due</th><th>Status</th><th>Operation</th></tr></thead><tbody>${rows.map(x => `<tr><td><b>${esc(x.id)}</b></td><td>${esc(x.consignee)}</td><td>${esc(x.origin)} <span class="muted">→</span> ${esc(x.dest)}</td><td>${money(x.cost)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.id)}">Update status</button></td></tr>`).join('')}</tbody></table></div>` : `<div class="empty">No cargo records returned by the backend.</div>`; }
function overview() { const p=state.data.packages||[], n=state.data.notifications||[], c=state.data.commissions||[]; const collected=p.filter(x=>x.status==='collected').length, revenue=p.reduce((a,x)=>a+Number(x.cost||0),0), pending=n.filter(x=>(x.status||'').toUpperCase()==='PENDING').length; return `<section class="metrics">${metric('Total shipments',p.length,'Live cargo records','blue')}${metric('Collected',collected,`${p.length?Math.round(collected/p.length*100):0}% completion rate`,'green')}${metric('Cargo value',money(revenue),'From live cargo records','amber')}${metric('Payment review',pending,pending?'Needs attention':'All caught up','red')}</section><section class="panel"><div class="panel-head"><div><h2>Recent cargo</h2><p>Synced from cargo_packages</p></div></div>${shipmentTable(p.slice(0,12))}</section>`; }
async function commission(id, rpc) { try { const body = rpc === 'approve_commission' ? {_id:id} : {_id:id,_reference:prompt('M-Pesa/payment reference') || ''}; if (rpc !== 'approve_commission' && !body._reference) return; await request(`rest/v1/rpc/${rpc}`, {method:'POST',body:JSON.stringify(body)}); toast(rpc==='approve_commission'?'Commission approved.':'Commission marked paid.'); await refreshData(); } catch(e) { toast(`Action failed: ${e.message}`,'error'); } }
async function openShipment(id) { const cargo=(state.data.packages||[]).find(x=>x.id===id); const next=prompt(`Update ${id}: registered, paid, or collected`, cargo?.status || 'registered'); if (!next || !['registered','paid','collected'].includes(next.toLowerCase())) return toast('Choose registered, paid, or collected.','error'); const patch={status:next.toLowerCase()}; if (patch.status==='paid') patch.paid_at=new Date().toISOString(); if (patch.status==='collected') patch.collected_at=new Date().toISOString(); try { await request(`rest/v1/cargo_packages?id=eq.${encodeURIComponent(id)}`, {method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)}); toast(`Cargo ${id} updated.`); await refreshData(); } catch(e) { toast(`Status update failed: ${e.message}`,'error'); } }
async function refreshData() {
  state.busy=true; render();
  const get = async path => { try { return await request(path); } catch (e) { console.warn(path,e); return []; } };
  const [packages, notifications, commissions, audits, broadcasts, directEmployees] = await Promise.all([
    get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'), get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),
    get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'), get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),
    get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'), get('rest/v1/employees?select=*&order=full_name.asc')
  ]);
  let employees = directEmployees;
  if (!employees.length) { try { const api = await request('api/public/admin/employees'); employees = api.employees || api || []; } catch {} }
  state.data={packages,notifications,commissions,audits,broadcasts,employees}; state.busy=false; render();
}
function shipmentTable(rows) { return rows.length?`<div class="table-wrap"><table><thead><tr><th>Photo</th><th>Tracking</th><th>Consignee</th><th>Route</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.package_photo_url?`<button class="photo-btn" data-photo="${esc(x.package_photo_url)}">View</button>`:'<span class="muted">No photo</span>'}</td><td><b>${esc(x.id)}</b></td><td>${esc(x.consignee)}<br><small>${esc(x.phone)}</small></td><td>${esc(x.origin)} → ${esc(x.dest)}</td><td>${money(x.cost)}</td><td>${status(x.status)}</td><td><button class="row-btn" data-track="${esc(x.id)}">Update</button> <button class="row-btn" data-reminder="${esc(x.id)}">Reminder</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No cargo records returned by the backend.</div>`; }
function overview() { const p=state.data.packages||[], people=new Set(p.map(x=>x.phone).filter(Boolean)).size, paid=p.filter(x=>x.status==='paid').length, collected=p.filter(x=>x.status==='collected').length, registered=p.filter(x=>x.status==='registered').length; const max=Math.max(1,registered,paid,collected); return `<section class="metrics">${metric('Packages registered',p.length,'Live cargo records','blue')}${metric('Clients served',people,'Unique consignee phones','green')}${metric('Ready for collection',paid,'Paid packages in warehouse','amber')}${metric('Collected',collected,'Completed handovers','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Cargo lifecycle</h2><p>Live distribution from cargo_packages</p></div></div><div class="flow">${[['registered',registered],['paid',paid],['collected',collected]].map(([name,count])=>`<div><b>${count}</b><span>${name}</span><i style="width:${Math.max(8,count/max*100)}%"></i></div>`).join('')}</div></article><article class="panel"><div class="panel-head"><div><h2>Revenue view</h2><p>Registered cargo value</p></div></div><div class="metric green"><span>Total cargo value</span><strong>${money(p.reduce((sum,x)=>sum+Number(x.cost||0),0))}</strong><small>${state.data.commissions?.length||0} commission records · ${(state.data.employees||[]).length} staff</small></div></article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Photo, status and reminder actions</p></div></div>${shipmentTable(p.slice(0,10))}</section>`; }
async function viewPhoto(path) { try { const url=`${state.connection.url}/storage/v1/object/${path.replace(/^\//,'')}`; const response=await fetch(url,{headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`}}); if(!response.ok) throw new Error('Photo unavailable'); const objectUrl=URL.createObjectURL(await response.blob()); const w=window.open(); w.document.write(`<title>DEX package photo</title><img src="${objectUrl}" style="max-width:100%;height:auto">`); } catch(e){toast(e.message,'error');} }
async function copyReminder(id) { const pkg=(state.data.packages||[]).find(x=>x.id===id); if(!pkg)return; const language=prompt('Type EN for English or ZH for Chinese','EN'); const name=pkg.consignee||'Customer'; const english=`Hello ${name}, this is DEX Cargo. This is a reminder that your package (${pkg.id}) is currently in our warehouse in Nairobi. Please come and pick it up. Thank you.`; const chinese=`您好，${name}。这里是 DEX Cargo。提醒您：您的包裹（${pkg.id}）目前在我们内罗毕的仓库。请您前来领取。谢谢。`; await navigator.clipboard.writeText(String(language).toUpperCase()==='ZH'?chinese:english); toast('Client reminder copied to clipboard.'); }
