function overview() { const p=state.data.packages||[], staff=state.data.employees||[], commissions=state.data.commissions||[], people=new Set(p.map(x=>x.phone).filter(Boolean)).size, paid=p.filter(x=>x.status==='paid').length, collected=p.filter(x=>x.status==='collected').length, registered=p.filter(x=>x.status==='registered').length, max=Math.max(1,registered,paid,collected); return `<section class="metrics">${metric('Packages registered',p.length,'Live cargo records','blue')}${metric('Clients served',people,'Unique consignee phones','green')}${metric('Active staff',staff.filter(x=>x.is_active).length,`${staff.length} employee records from backend`,'amber')}${metric('Commissions',commissions.length,commissions.length?'Live commission records':'No commission records in backend','red')}</section><section class="grid two"><article class="panel"><div class="panel-head"><div><h2>Cargo lifecycle</h2><p>Live distribution from cargo_packages</p></div></div><div class="flow">${[['registered',registered],['paid',paid],['collected',collected]].map(([name,count])=>`<div><b>${count}</b><span>${name}</span><i style="width:${Math.max(8,count/max*100)}%"></i></div>`).join('')}</div></article><article class="panel"><div class="panel-head"><div><h2>Live employee roster</h2><p>Directly from employees table</p></div><button class="text-btn" data-goto="staff">Open staff →</button></div>${staff.length?staff.slice(0,5).map(x=>`<div class="action"><span>◉</span><div><b>${esc(x.full_name)} · ${esc(x.employee_code)}</b><small>${esc(x.role)} · ${x.is_active?'Active':'Inactive'}</small></div></div>`).join(''):'<div class="empty">No employee rows returned.</div>'}</article></section><section class="panel"><div class="panel-head"><div><h2>Latest packages</h2><p>Photo, status and reminder actions</p></div></div>${shipmentTable(p.slice(0,10))}</section>`; }
const ADMIN_BACKEND = window.__DEX_ADMIN_BACKEND__ || 'https://project--5e9b81ad-6c63-4331-af7a-01008019e17f.lovable.app';
async function adminRequest(path, options={}) { const response = await fetch(`${ADMIN_BACKEND}${path}`, {...options,headers:{Authorization:`Bearer ${state.session.access_token}`,...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}}); if(!response.ok) throw new Error(readableError(await response.text() || `Admin request failed (${response.status})`)); const text=await response.text(); return text?JSON.parse(text):null; }
async function refreshData() { state.busy=true; render(); const get=async p=>{try{return await request(p)}catch(e){console.warn(e);return[]}}; const [packages,notifications,commissions,audits,broadcasts,employees]=await Promise.all([get('rest/v1/cargo_packages?select=*&order=registered_at.desc&limit=500'),get('rest/v1/payment_notifications?select=*&order=uploaded_at.desc&limit=200'),get('rest/v1/commissions?select=*&order=created_at.desc&limit=300'),get('rest/v1/audit_logs?select=*&order=timestamp.desc&limit=150'),get('rest/v1/broadcast_messages?select=*&order=timestamp.desc&limit=50'),adminRequest('/api/public/admin/employees').then(x=>x.employees||[]).catch(()=>get('rest/v1/employees?select=*&order=full_name.asc'))]); state.data={packages,notifications,commissions,audits,broadcasts,employees};state.busy=false;render(); }
function staff() { const rows=state.data.employees||[]; return `<section class="toolbar"><p class="muted">Manage staff through the secured DEX administrator backend.</p><button class="primary" id="add-staff">+ Add team member</button></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Code</th><th>Role</th><th>Contact</th><th>Commission</th><th>Access</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.full_name)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.employee_code)}</td><td>${status(x.role)}</td><td>${esc(x.phone)}</td><td>${x.commission_percentage??0}%</td><td><button class="toggle ${x.is_active?'on':''}" data-employee="${x.id}" data-active="${x.is_active}"><i></i>${x.is_active?'Active':'Inactive'}</button></td><td><button class="row-btn" data-edit-employee="${esc(x.id)}">Edit information</button> ${x.role==='admin'?'':`<button class="row-btn" data-delete-employee="${x.id}">Delete</button>`}</td></tr>`).join('')}</tbody></table></div></section>`; }
function payments() { const rows=state.data.notifications||[]; return `<section class="grid broadcast-grid"><article class="panel compose"><h2>Upload payment evidence</h2><p>Admin uploads an image or text; staff can link it to cargo.</p><form id="payment-upload"><label>Evidence type<select name="evidence_type"><option value="IMAGE">Screenshot / image</option><option value="TEXT">Text / M-Pesa message</option></select></label><label>Screenshot<input name="image" type="file" accept="image/*"></label><label>Payment text<textarea name="text_content" placeholder="Paste M-Pesa or payment message"></textarea></label><label>Amount (KES)<input name="amount" type="number" min="1"></label><label>Sender phone<input name="sender_phone" placeholder="07…"></label><button class="primary" type="submit">Upload payment evidence</button></form></article><article class="panel"><div class="panel-head"><div><h2>Payment queue</h2><p>Link a payment to its package.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Amount</th><th>Phone</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${money(x.amount)}</td><td>${esc(x.sender_phone)}</td><td>${status(x.status)}</td><td>${(x.status||'').toUpperCase()==='LINKED'?'Linked':`<button class="row-btn" data-link-payment="${x.id}">Link package</button>`}</td></tr>`).join('')}</tbody></table></div></article></section>`; }
async function createEmployee() { const full_name=prompt('Full name'); if(!full_name)return; const email=prompt('Email'); const password=prompt('Temporary password (8+ characters)'); const phone=prompt('Phone (optional)')||null; const role=prompt('Role: sales_rep, logistics_manager, sales_manager, or admin','sales_rep'); const commission_percentage=Number(prompt('Commission percentage','0')); try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify({full_name,email,password,phone,role,commission_percentage})});toast('Team member created.');await refreshData()}catch(e){toast(e.message,'error')} }
async function editEmployee(id) { const employee=(state.data.employees||[]).find(x=>String(x.id)===String(id)); if(!employee)return toast('Employee was not found. Refresh and try again.','error'); const full_name=prompt('Full name',employee.full_name||''); if(full_name===null)return; const email=prompt('Email',employee.email||''); if(email===null)return; const phone=prompt('Phone (optional)',employee.phone||''); if(phone===null)return; const role=prompt('Role: sales_rep, sales_manager, logistics_manager, finance_manager, or admin',employee.role||'sales_rep'); if(role===null)return; try { await adminRequest('/api/public/admin/employees',{method:'PATCH',body:JSON.stringify({employee_id:id,is_active:Boolean(employee.is_active),full_name:full_name.trim(),email:email.trim(),phone:phone.trim()||null,role:role.trim()})}); toast('Employee information updated.'); await refreshData(); } catch(e) { toast(`Employee details were not saved: ${e.message}`,'error'); } }

async function deleteEmployee(id) { if(!confirm('Permanently delete this employee and their login?'))return; try{await adminRequest('/api/public/admin/delete-user',{method:'POST',body:JSON.stringify({employee_id:id})});toast('Employee deleted.');await refreshData()}catch(e){toast(e.message,'error')} }
async function uploadPayment(form) { const f=new FormData(form), type=f.get('evidence_type'), file=f.get('image'); if(type==='IMAGE'&&(!file||!file.size))return toast('Choose a screenshot.','error'); if(type==='TEXT'&&!f.get('text_content').trim())return toast('Enter payment text.','error'); let image_url=null; try{if(type==='IMAGE'){const filename=`payment_${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const r=await fetch(`${state.connection.url}/storage/v1/object/proofs/${filename}`,{method:'POST',headers:{apikey:state.connection.key,Authorization:`Bearer ${state.session.access_token}`,'Content-Type':file.type},body:file});if(!r.ok)throw new Error(await r.text());image_url=`proofs/${filename}`;}const id=`PN-${Date.now()}`, notification_number=`PAY-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Date.now().toString().slice(-4)}`;await request('rest/v1/payment_notifications',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id,notification_number,evidence_type:type,image_url,text_content:f.get('text_content')||null,uploaded_by:state.profile?.name||'Admin',uploaded_at:new Date().toISOString(),status:'PENDING',amount:Number(f.get('amount'))||null,sender_phone:f.get('sender_phone')||null,timestamp:new Date().toISOString()})});toast('Payment evidence uploaded.');await refreshData()}catch(e){toast(`Upload failed: ${e.message}`,'error')} }
async function linkPayment(id) { const pkgId=prompt('Tracking number to link'); if(!pkgId)return; const n=(state.data.notifications||[]).find(x=>x.id===id); try{await request('rest/v1/payment_allocations',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({id:`PA-${Date.now()}`,payment_notification_id:id,order_id:pkgId,tracking_number:pkgId,allocated_amount:Number(n?.amount)||0,linked_by:state.profile?.name||'Admin',linked_at:new Date().toISOString(),notification_number:n?.notification_number||null})});toast('Payment linked to package.');await refreshData()}catch(e){toast(`Link failed: ${e.message}`,'error')} }
