/* External carrier lookup. Results are deliberately opened in the user's
   default browser: tracking providers block embedded/automated scraping. */
function trackingNumber(pkg){return String(pkg?.tracking_number||pkg?.id||'').trim()}
function openTrackingProvider(provider,number){const code=encodeURIComponent(number);const url=provider==='17track'?`https://t.17track.net/en#nums=${code}`:`https://parcelsapp.com/en/tracking/${code}`;window.dexAdmin.openExternal(url).then(ok=>{if(!ok)toast('Could not open the tracking provider.','error')})}
function trackPackage(id){const pkg=(state.data.packages||[]).find(p=>String(p.id)===String(id)||String(p.tracking_number)===String(id));const number=trackingNumber(pkg);if(!number)return toast('This package has no tracking number.','error');const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · EXTERNAL TRACKING</p><h2>Track ${esc(number)}</h2><p>17TRACK is the primary lookup. If it does not return an event, use ParcelsApp as the fallback.</p><div class="status-actions"><button class="row-btn selected-status" data-open-tracker="17track">Open 17TRACK</button><button class="row-btn" data-open-tracker="parcels">Open ParcelsApp fallback</button></div><p class="muted" style="margin-top:14px">The tracking number is passed to the chosen provider. DEX does not save or scrape their tracking results.</p>`);modal.querySelectorAll('[data-open-tracker]').forEach(button=>button.onclick=()=>{openTrackingProvider(button.dataset.openTracker,number);modal.remove()})}
function packageTable(rows,title='Packages'){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2><p>${rows.length} package${rows.length===1?'':'s'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Package image</th><th>Tracking</th><th>Client</th><th>Route / freight</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.package_photo_url?`<button class="package-thumb" data-photo="${esc(x.package_photo_url)}"><img alt="Package image"><span>View</span></button>`:'<div class="package-thumb empty-thumb">No image</div>'}</td><td><b>${esc(x.tracking_number||x.id)}</b></td><td>${esc(x.consignee)}<br><small>${esc(x.phone)}</small></td><td>${esc(x.origin)} → ${esc(x.dest)}<br><small>${esc(x.mode||x.cargo_category||'Freight mode not set')}</small></td><td>${money(packageValue(x))}</td><td>${status(x.status)}</td><td><button class="row-btn" data-external-track="${esc(x.id||x.tracking_number)}">Track</button> <button class="row-btn" data-reminder="${esc(x.id)}">Copy reminder</button> <button class="row-btn" data-track="${esc(x.id)}">Update</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No packages in this group.</td></tr>'}</tbody></table></div></section>`}
