// Final account and payment workspace overrides.  This renderer intentionally
// keeps the last definitions authoritative while older app releases remain in
// the same file.
function accountErrorMessage(value){
  const raw=String(value?.message||value||'Unable to create the account.');
  const json=raw.match(/\{[\s\S]*\}/);let parsed='';
  try{parsed=json?String(JSON.parse(json[0]).error||''):''}catch{}
  const message=(parsed||raw).replace(/^Create user failed:\s*/i,'').trim();
  if(/weak|easy to guess|compromised password/i.test(message))return 'Choose a stronger temporary password: 12 or more characters with uppercase, lowercase, a number, and a symbol. Do not use a common password.';
  if(/already|registered|exists|duplicate/i.test(message))return 'That email address is already registered. Use a different email address.';
  return readableError(message);
}
function validTemporaryPassword(value){return String(value||'').length>=12&&/[a-z]/.test(value)&&/[A-Z]/.test(value)&&/\d/.test(value)&&/[^A-Za-z0-9]/.test(value)}
function createEmployee(){
  const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · STAFF ACCESS</p><h2>Add team member</h2><p>Create an active account with the exact company role selected below.</p><form id="employee-form"><label>Full name<input name="full_name" minlength="2" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Temporary password<input name="password" type="password" minlength="12" autocomplete="new-password" required aria-describedby="password-help"></label><p id="password-help" class="muted">Use 12+ characters, including uppercase, lowercase, a number, and a symbol. Avoid common passwords.</p><label>Company role<select name="role"><option value="sales_rep">Sales representative</option><option value="sales_manager">Sales manager</option><option value="logistics_manager">Logistics manager</option><option value="finance_manager">Finance manager</option><option value="admin">Administrator</option></select></label><p class="form-progress" data-create-progress aria-live="polite"></p><div class="dialog-actions"><button class="primary" type="submit">Create team member</button><button class="secondary" type="button" data-cancel-create>Cancel</button></div></form>`);
  modal.querySelector('[data-cancel-create]').onclick=()=>modal.remove();
  const form=modal.querySelector('#employee-form'),password=form.querySelector('[name="password"]'),progress=modal.querySelector('[data-create-progress]');
  password.addEventListener('input',()=>{progress.textContent=password.value&&!validTemporaryPassword(password.value)?'Password needs 12+ characters with uppercase, lowercase, a number, and a symbol.':''});
  form.addEventListener('submit',async event=>{
    event.preventDefault();
    if(!validTemporaryPassword(password.value)){const message='Choose a stronger temporary password before creating the account.';progress.textContent=message;toast(message,'error');password.focus();return;}
    const button=form.querySelector('button[type="submit"]'),body=Object.fromEntries(new FormData(form));
    button.disabled=true;button.textContent='Creating account…';progress.textContent='Creating the staff account and assigning the selected role…';
    try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify({...body,phone:body.phone?.trim()||null,commission_percentage:0})});modal.remove();toast('Team member created successfully.');await refreshData();}
    catch(error){const message=accountErrorMessage(error);button.disabled=false;button.textContent='Create team member';progress.textContent=message;toast(message,'error');}
  });
}
