/* Payment archive, commission assignment and international-forwarding
   workspace.  These declarations are intentionally last in this legacy
   single-file renderer, making them the authoritative implementations. */
function commissionEmployeeOptions(selected='',includeKeep=false){
  const first=includeKeep?'<option value="__keep">Use current package assignment</option>':'<option value="">No commission employee assigned</option>';
  return first+commissionEligibleEmployees().map(employee=>`<option value="${esc(employee.id)}" ${String(employee.id)===String(selected)?'selected':''}>${esc(employee.full_name||employee.email||employee.employee_code)} · ${esc(String(employee.role||'').replaceAll('_',' '))}</option>`).join('');
}

