createEmployee=function(){const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · STAFF ACCESS</p><h2>Add team member</h2><form id="employee-form"><label>Full name<input name="full_name" minlength="2" required></label><label>Email<input name="email" type="email" required></label><label>Phone (optional)<input name="phone" type="tel"></label><label>Temporary password<input name="password" type="password" minlength="8" required></label><p class="muted">Choose the temporary password for this team member.</p><label>Company role<select name="role"><option value="sales_rep">Sales representative</option><option value="sales_manager">Sales manager</option><option value="logistics_manager">Logistics manager</option><option value="finance_manager">Finance manager</option><option value="admin">Administrator</option></select></label><p class="form-progress" data-create-progress aria-live="polite"></p><div class="dialog-actions"><button class="primary" type="submit">Create team member</button><button class="secondary" type="button" data-cancel-create>Cancel</button></div></form>`);modal.querySelector('[data-cancel-create]').onclick=()=>modal.remove();const form=modal.querySelector('#employee-form'),progress=modal.querySelector('[data-create-progress]');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]'),body=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent='Creating account…';progress.textContent='Creating the staff account…';try{await adminRequest('/api/public/admin/employees',{method:'POST',body:JSON.stringify({...body,phone:body.phone?.trim()||null,commission_percentage:0})});modal.remove();toast('Team member created successfully.');await refreshData()}catch(error){const message=accountErrorMessage(error);button.disabled=false;button.textContent='Create team member';progress.textContent=message;toast(message,'error')}}}
function extractPaymentAmount(text){
  const value=String(text||'');
  const match=value.match(/(?:Ksh|KES)\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)/i);
  return match?Number(String(match[1]).replace(/,/g,'')):null;
}
function paymentAmount(payment){
  const stored=Number(payment?.amount);
  return Number.isFinite(stored)&&stored>0?stored:(extractPaymentAmount(payment?.text_content)||0);
}
payments=function(){const all=state.data.notifications||[],view=state.paymentEvidenceView||'pending',pending=all.filter(x=>String(x.status||'').toUpperCase()!=='LINKED'),linked=all.filter(x=>String(x.status||'').toUpperCase()==='LINKED'),rows=view==='linked'?linked:pending;return `<section class="panel compose"><div class="panel-head"><div><h2>Upload payment evidence</h2><p>Choose an image from this device, paste a copied image, or paste payment text. M-PESA amounts are detected automatically.</p></div></div><form id="payment-upload"><label>Evidence type<select id="evidence-type" name="evidence_type"><option value="IMAGE">Payment screenshot</option><option value="TEXT">Text payment message</option></select></label><div class="payment-paste-tools"><button class="secondary" type="button" data-paste-payment-text>Paste copied text</button><span class="muted">For text you can also focus the message box and press Ctrl+V. For an image, copy it and press Ctrl+V anywhere in this form, or choose a local image below.</span></div><label id="image-field">Choose image from this device<input name="image" type="file" accept="image/*"></label><label id="note-field">Note attached to image (optional)<textarea name="image_note" placeholder="Optional internal note"></textarea></label><label id="text-field" style="display:none">Payment message<textarea name="text_content" placeholder="Paste the M-Pesa / payment message"></textarea><small class="payment-amount-hint" data-payment-amount-preview>Detected amount: Ksh 0.00</small></label><button class="primary" type="submit">Save payment evidence to backend</button></form></section><section class="panel"><div class="panel-head"><div><h2>${view==='linked'?'Linked payment evidence':'Payment evidence awaiting link'}</h2><p>${view==='linked'?'Archived evidence allocated to paid packages.':'Link evidence to one or multiple unpaid packages.'}</p></div><span class="count">${rows.length} records</span></div><div class="category-tabs evidence-tabs"><button class="${view==='pending'?'active':''}" onclick="state.paymentEvidenceView='pending';render()">Awaiting link <span>${pending.length}</span></button><button class="${view==='linked'?'active':''}" onclick="state.paymentEvidenceView='linked';render()">Linked evidence <span>${linked.length}</span></button></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Evidence</th><th>Details</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.notification_number||x.id)}</b></td><td>${x.image_url?`<button class="evidence-preview" data-evidence-image="${esc(x.image_url)}" title="Click to view full payment screenshot"><img data-evidence-thumb="${esc(x.image_url)}" alt="Payment evidence thumbnail"><span>View image</span></button>`:`<button class="row-btn" data-evidence-text="${esc(x.text_content||'No payment message was attached.')}">View text</button>`}</td><td><div class="evidence-note">${esc(x.text_content||'No note attached')}</div></td><td><b class="payment-amount">${money(paymentAmount(x))}</b></td><td>${status(x.status||'PENDING')}</td><td>${view==='linked'?'<span class="muted">Archived · linked</span>':`<button class="row-btn" data-link-payment="${esc(x.id)}">Link package(s)</button> <button class="row-btn danger" data-delete-payment="${esc(x.id)}">Delete evidence</button>`}</td></tr>`).join('')||`<tr><td colspan="6" class="empty">${view==='linked'?'No linked payment evidence yet.':'No payment evidence is awaiting a link.'}</td></tr>`}</tbody></table></div></section>`}
paymentLinkDialog=function(id){const evidence=(state.data.notifications||[]).find(x=>String(x.id)===String(id)),packages=livePackageRows().filter(x=>!isPaidPackage(x));if(!evidence)return toast('Payment evidence was not found. Refresh and try again.','error');if(!packages.length)return toast('There are no unpaid packages available to link.','error');const rows=packages.map(p=>`<label class="payment-package-row" data-payment-search-row><input type="checkbox" value="${esc(p.id)}" data-payment-package><span class="payment-package-main"><b>${esc(p.tracking_number||p.id)}</b><small>${esc(p.consignee||'Unassigned client')}${p.phone?` · ${esc(p.phone)}`:''}</small></span><span class="payment-package-meta">${status(p.cargo_category||'general')}<small>${packagePrice(p)}</small></span></label>`).join('');const modal=packageDialog(`<p class="eyebrow">DEX LOGISTICS · PAYMENT RECONCILIATION</p><h2>Link payment evidence</h2><p>Selected packages become Paid; the evidence moves to Linked evidence.</p><div class="payment-link-search"><span>⌕</span><input type="search" data-payment-search placeholder="Search client name, tracking number, or phone"></div><div class="payment-link-count"><span data-visible-count>${packages.length}</span> unpaid packages shown</div><div class="package-link-list payment-picker">${rows}</div><div class="dialog-actions"><button class="primary" data-confirm-payment-link>Link selected packages</button><button class="secondary" data-close-payment-link>Cancel</button></div>`);modal.querySelector('[data-close-payment-link]').onclick=()=>modal.remove();modal.querySelector('[data-payment-search]').oninput=event=>{const query=String(event.target.value||'').toLocaleLowerCase().trim();let shown=0;modal.querySelectorAll('[data-payment-search-row]').forEach(row=>{const match=!query||String(row.textContent||'').toLocaleLowerCase().includes(query);row.style.display=match?'grid':'none';if(match)shown++});modal.querySelector('[data-visible-count]').textContent=shown};modal.querySelector('[data-confirm-payment-link]').onclick=async event=>{const button=event.currentTarget,chosen=[...modal.querySelectorAll('[data-payment-package]:checked')].map(input=>input.value);if(!chosen.length)return toast('Select at least one package.','error');button.disabled=true;button.textContent='Linking packages…';try{await adminRequest('/api/public/link-payment',{method:'POST',body:JSON.stringify({payment_notification_id:id,allocations:chosen.map(package_id=>({package_id}))})});modal.remove();state.paymentEvidenceView='linked';toast(`${chosen.length} package${chosen.length===1?'':'s'} marked Paid; evidence moved to Linked evidence.`);await refreshData()}catch(error){button.disabled=false;button.textContent='Link selected packages';toast(`Payment link failed: ${error.message}`,'error')}}}

